public class ArrayUtils {
    public static final Byte[] EMPTY_BYTE_ARRAY = new Byte[0];

    /** 
     * <p>Defensive programming technique to change a <code>null</code> reference to an empty one.</p> <p>This method returns an empty array for a <code>null</code> input array.</p> <p>As a memory optimizing technique an empty array passed in will be overridden with the empty <code>public static</code> references in this class.</p>
     * @param array  the array to check for <code>null</code> or empty
     * @return the same array, <code>public static</code> empty array if <code>null</code> or empty input
     * @since 2.5
     */
    public static Byte[] nullToEmpty(final Byte[] array) {
        if (array == null || array.length == 0) {
            return EMPTY_BYTE_ARRAY;
        }
        return array;
    }

    public static void main(String[] args) {
        Byte[] testArray = null;
        Byte[] resultArray = nullToEmpty(testArray);
        System.out.println("Resulting array length: " + resultArray.length); // Should print 0

        Byte[] emptyArray = new Byte[0];
        resultArray = nullToEmpty(emptyArray);
        System.out.println("Resulting array length: " + resultArray.length); // Should print 0

        Byte[] nonEmptyArray = {1, 2, 3};
        resultArray = nullToEmpty(nonEmptyArray);
        System.out.println("Resulting array length: " + resultArray.length); // Should print 3
    }
}

