import java.util.Objects;

public class ByteConverter {
    /** 
     * <p>Converts an array of object Bytes to primitives.</p> <p>This method returns <code>null</code> for a <code>null</code> input array.</p>
     * @param array  a <code>Byte</code> array, may be <code>null</code>
     * @return a <code>byte</code> array, <code>null</code> if null array input
     * @throws NullPointerException if array content is <code>null</code>
     */
    public static byte[] toPrimitive(final Byte[] array) {
        if (array == null) {
            return null;
        }
        final byte[] result = new byte[array.length];
        for (int i = 0; i < array.length; i++) {
            result[i] = Objects.requireNonNull(array[i], "Array content cannot be null");
        }
        return result;
    }

    public static void main(String[] args) {
        Byte[] byteObjects = {1, 2, 3, 4, 5};
        byte[] bytePrimitives = toPrimitive(byteObjects);

        if (bytePrimitives != null) {
            for (byte b : bytePrimitives) {
                System.out.print(b + " ");
            }
        }
    }
}

