import java.util.HashMap;
import java.util.Map;

public class SymbolTable {
    private static class Symbol {
        String name;
        String descriptor;

        Symbol(String name, String descriptor) {
            this.name = name;
            this.descriptor = descriptor;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            Symbol symbol = (Symbol) o;
            return name.equals(symbol.name) && descriptor.equals(symbol.descriptor);
        }

        @Override
        public int hashCode() {
            int result = name.hashCode();
            result = 31 * result + descriptor.hashCode();
            return result;
        }
    }

    private Map<Symbol, Integer> constantPool = new HashMap<>();
    private int nextIndex = 1;

    public int addConstantNameAndType(final String name, final String descriptor) {
        Symbol symbol = new Symbol(name, descriptor);
        if (constantPool.containsKey(symbol)) {
            return constantPool.get(symbol);
        } else {
            constantPool.put(symbol, nextIndex);
            return nextIndex++;
        }
    }

    public static void main(String[] args) {
        SymbolTable symbolTable = new SymbolTable();
        System.out.println(symbolTable.addConstantNameAndType("field1", "I")); // Should print 1
        System.out.println(symbolTable.addConstantNameAndType("method1", "()V")); // Should print 2
        System.out.println(symbolTable.addConstantNameAndType("field1", "I")); // Should print 1
    }
}

