class DoublyLinkedList<E> {
    private ListNode<E> head;
    private ListNode<E> tail;
    private final Lock lock = new ReentrantLock();

    private void addListNode(ListNodeImpl<E> node) {
        lock.lock();
        try {
            if (head == null) {
                head = tail = node;
            } else {
                tail.next = node;
                node.prev = tail;
                tail = node;
            }
        } finally {
            lock.unlock();
        }
    }

    private void removeListNode(ListNodeImpl<E> node) {
        lock.lock();
        try {
            if (node.prev != null) {
                node.prev.next = node.next;
            } else {
                head = node.next;
            }
            if (node.next != null) {
                node.next.prev = node.prev;
            } else {
                tail = node.prev;
            }
            node.prev = node.next = null;
        } finally {
            lock.unlock();
        }
    }

    private void moveAllListNodes(DoublyLinkedList<E> list) {
        ListNode<E> current = list.head;
        while (current != null) {
            ListNode<E> next = current.next;
            list.removeListNode((ListNodeImpl<E>) current);
            addListNode((ListNodeImpl<E>) current);
            current = next;
        }
    }
}

class ListNodeImpl<E> extends ListNode<E> {
    ListNodeImpl(E data) {
        super(data);
    }
}

