import java.util.Set;
import java.util.HashSet;

public class GraphIterator {
    private Set<Integer> visited;
    private Set<Integer> allVertices;

    public GraphIterator(Set<Integer> allVertices) {
        this.visited = new HashSet<>();
        this.allVertices = allVertices;
    }

    public void visit(int vertex) {
        visited.add(vertex);
    }

    /** 
     * Checks whether there exist unvisited vertices.
     * @return true if there exist unvisited vertices.
     */
    @Override 
    public boolean hasNext(){
        return allVertices.size() > visited.size();
    }

    public static void main(String[] args) {
        Set<Integer> vertices = Set.of(1, 2, 3, 4, 5);
        GraphIterator iterator = new GraphIterator(vertices);
        System.out.println(iterator.hasNext()); // true
        iterator.visit(1);
        System.out.println(iterator.hasNext()); // true
        iterator.visit(2);
        iterator.visit(3);
        iterator.visit(4);
        iterator.visit(5);
        System.out.println(iterator.hasNext()); // false
    }
}

