public class Graph<V, E> {
    private Set<E> edges;

    // Assuming each edge has a method to get its source and target vertices
    public interface Edge<V> {
        V getSource();
        V getTarget();
    }

    public Graph(Set<E> edges) {
        this.edges = edges;
    }

    private Set<V> initVisibleVertices() {
