import org.jgrapht.Graph;
import org.jgrapht.GraphPath;
import org.jgrapht.Graphs;
import org.jgrapht.alg.shortestpath.DijkstraShortestPath;
import org.jgrapht.graph.DefaultDirectedGraph;
import org.jgrapht.graph.DefaultEdge;
import java.util.Set;

public class GraphPathConverter<V, E extends DefaultEdge> {

    protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
        if (tour == null || tour.isEmpty()) {
            throw new IllegalArgumentException("Tour set cannot be null or empty");
        }

        // Create a path from the edge set
        V startVertex = null;
        for (E edge : tour) {
            if (startVertex == null) {
                startVertex = graph.getEdgeSource(edge);
            }
            V targetVertex = graph.getEdgeTarget(edge);
        }

        // Reconstruct the path
        V currentVertex = startVertex;
        GraphPath<V, E> path = new org.jgrapht.alg.shortestpath.GraphPathImpl<>(graph, startVertex, null, 0.0);

        for (E edge : tour) {
            if (!path.getEdgeList().contains(edge)) {
                path.getVertexList().add(currentVertex);
                path.getEdgeList().add(edge);
                currentVertex = graph.getEdgeTarget(edge);
            }
        }
        path.getVertexList().add(currentVertex); // Add the last vertex

        return path;
    }

    public static void main(String[] args) {
        Graph<Integer, DefaultEdge> graph = new DefaultDirectedGraph<>(DefaultEdge.class);
        Graphs.addAllVertices(graph, Set.of(1, 2, 3, 4));
        graph.addEdge(1, 2);
        graph.addEdge(2, 3);
        graph.addEdge(3, 4);
        graph.addEdge(4, 1);

        Set<DefaultEdge> tour = Set.of(graph.getEdge(1, 2), graph.getEdge(2, 3), graph.getEdge(3, 4), graph.getEdge(4, 1));

        GraphPathConverter<Integer, DefaultEdge> converter = new GraphPathConverter<>();
        GraphPath<Integer, DefaultEdge> path = converter.edgeSetToTour(tour, graph);

        System.out.println("Path: " + path.getVertexList());
    }
}

