import java.util.Arrays;

public class SparseMatrix {
    private int[][] matrix;

    public SparseMatrix(int[][] matrix) {
        this.matrix = matrix;
    }

    /** 
     * Get the number of non-zero entries of a row.
     * @param row the row
     * @return the number of non-zero entries of a row
     */
    public int nonZeros(int row) {
        if (row < 0 || row >= matrix.length) {
            throw new IllegalArgumentException("Row index out of bounds");
        }
        return (int) Arrays.stream(matrix[row]).filter(entry -> entry != 0).count();
    }

    public static void main(String[] args) {
        int[][] matrix = {
            {0, 1, 0, 2},
            {0, 0, 0, 0},
            {3, 0, 4, 0}
        };
        SparseMatrix sparseMatrix = new SparseMatrix(matrix);
        System.out.println(sparseMatrix.nonZeros(0)); // Output: 2
        System.out.println(sparseMatrix.nonZeros(1)); // Output: 0
        System.out.println(sparseMatrix.nonZeros(2)); // Output: 2
    }
}

