import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;

public class FileIterator {
    private final List<File> files;
    private int currentIndex;

    public FileIterator(String directoryPath, FilenameFilter filter) {
        File directory = new File(directoryPath);
        if (directory.isDirectory()) {
            files = new ArrayList<>(List.of(directory.listFiles(filter)));
        } else {
            files = new ArrayList<>();
        }
        currentIndex = 0;
    }

    public InputStream next() throws IOException {
        if (currentIndex >= files.size()) {
            return null;
        }
        File file = files.get(currentIndex++);
        return new FileInputStream(file);
    }

    public static void main(String[] args) {
        try {
            FileIterator iterator = new FileIterator(".", (dir, name) -> name.endsWith(".txt"));
            InputStream input;
            while ((input = iterator.next()) != null) {
                // Process the input stream
                input.close();
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

