import org.apache.logging.log4j.core.appender.AbstractAppender;
import java.util.concurrent.ArrayBlockingQueue;

public class LoggingEventBuffer extends AbstractAppender {
    private final ArrayBlockingQueue<LogEvent> buffer;

    public LoggingEventBuffer(String name, int bufferSize) {
        super(name, null, null, true);
        this.buffer = new ArrayBlockingQueue<>(bufferSize);
    }

    @Override
    public void append(LogEvent event) {
        put(event);
    }

    /**
     * Place a {@link LogEvent} in the buffer. If the buffer is full then the event is <b>silently dropped</b>.
     * It is the caller's responsibility to make sure that the buffer has free space.
     */
    public void put(LogEvent o) {
        buffer.offer(o);
    }

    public static void main(String[] args) {
        LoggingEventBuffer buffer = new LoggingEventBuffer("TestBuffer", 10);
        // Example usage
        buffer.put(LogEvent.newBuilder().build());
    }
}

